PASTE_JS = """async (cur) => {
  try {
    const t = await navigator.clipboard.readText();
    if (!t) return cur;
    return (cur && cur.trim()) ? (cur + "\\n\\n" + t) : t;
  } catch (e) { return cur; }
}"""
TITLE_JS = """() => {
  try {
    document.querySelector('#paste-btn button').title='Вставить из буфера обмена';
    document.querySelector('#clear-btn button').title='Очистить весь текст';
  } catch(e){}

  // Дорисовываем рамку двумя симметричными штрихами и ставим звезду в точке встречи.
  const drawFrame = () => {
    const salon = document.querySelector('#salon');
    if (!salon) return;
    let svg = salon.querySelector('.salon-frame-draw');
    if (!svg) {
      svg = document.createElementNS('http://www.w3.org/2000/svg','svg');
      svg.setAttribute('class','salon-frame-draw');
      svg.setAttribute('aria-hidden','true');
      svg.innerHTML = '<path class="frame-line left-line"/><path class="frame-line right-line"/>' +
        '<path class="frame-star" d="M0,-7 L1.8,-1.8 L7,0 L1.8,1.8 L0,7 L-1.8,1.8 L-7,0 L-1.8,-1.8 Z"/>';
      salon.appendChild(svg);
    }
    const w = salon.clientWidth + 10;
    const h = salon.clientHeight + 10;
    const sizeKey = `${w}x${h}`;
    if (svg.dataset.frameSize === sizeKey) return;
    svg.dataset.frameSize = sizeKey;
    svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
    const inset = 5, r = 4, cx = w/2, top = inset, bottom = h-inset;
    const left = `M ${cx} ${bottom} L ${inset+r} ${bottom} Q ${inset} ${bottom} ${inset} ${bottom-r} L ${inset} ${top+r} Q ${inset} ${top} ${inset+r} ${top} L ${cx} ${top}`;
    const right = `M ${cx} ${bottom} L ${w-inset-r} ${bottom} Q ${w-inset} ${bottom} ${w-inset} ${bottom-r} L ${w-inset} ${top+r} Q ${w-inset} ${top} ${w-inset-r} ${top} L ${cx} ${top}`;
    const paths = [svg.querySelector('.left-line'), svg.querySelector('.right-line')];
    [left,right].forEach((d,i) => {
      const path = paths[i]; path.setAttribute('d',d);
      const len = path.getTotalLength();
      path.style.strokeDasharray = len;
      path.style.strokeDashoffset = len;
      path.style.animation = 'none';
      void path.getBoundingClientRect();
      // Во время движения линия заметно светлее и слегка светится;
      // после соединения плавно возвращается к спокойному матовому золоту.
      path.style.animation = `frameDraw 1.5s cubic-bezier(.42,0,.25,1) .3s forwards, frameGlow 3.2s cubic-bezier(.4,0,.2,1) .3s forwards`;
    });
    const star = svg.querySelector('.frame-star');
    // Координаты самой звезды задаём непосредственно в SVG-пути:
    // это гарантирует точное положение в центре верхнего соединения.
    const sx = cx, sy = top;
    star.setAttribute('d', `M ${sx} ${sy-4.1} L ${sx+1.0} ${sy-1.0} L ${sx+4.1} ${sy} L ${sx+1.0} ${sy+1.0} L ${sx} ${sy+4.1} L ${sx-1.0} ${sy+1.0} L ${sx-4.1} ${sy} L ${sx-1.0} ${sy-1.0} Z`);
  };
  if (!document.querySelector('#salon-frame-keyframes')) {
    const style = document.createElement('style');
    style.id = 'salon-frame-keyframes';
    style.textContent = `@keyframes frameDraw { to { stroke-dashoffset:0; } } @keyframes frameGlow { 0% { stroke-width:4.35; filter:drop-shadow(0 0 2px rgba(255,230,166,.72)) drop-shadow(0 0 5px rgba(179,132,48,.42)); } 58% { stroke-width:4.35; filter:drop-shadow(0 0 3px rgba(255,246,218,.98)) drop-shadow(0 0 9px rgba(205,160,75,.72)); } 66% { stroke-width:4.35; filter:drop-shadow(0 0 2px rgba(255,230,166,.78)) drop-shadow(0 0 5px rgba(179,132,48,.42)); } 100% { stroke-width:1.45; filter:none; } }`;
    document.head.appendChild(style);
  }
  const apply = () => { try {
    const gc = document.querySelector('.gradio-container');
    const salon = document.querySelector('#salon');
    if (gc && salon) {
      gc.style.setProperty('display','flex','important');
      gc.style.setProperty('flex-direction','column','important');
      gc.style.setProperty('justify-content','center','important');
      gc.style.setProperty('min-height','100vh','important');
      let el = salon.parentElement;
      while (el && el !== gc) { el.style.setProperty('flex','0 0 auto','important'); el = el.parentElement; }
      drawFrame();
    }
  } catch(e){} };
  apply(); setTimeout(apply, 500); window.addEventListener('resize', apply);
}"""
with gr.Blocks(title="Аудиотекст", css=CSS) as demo:
    with gr.Column(elem_id="salon"):
        gr.HTML(
            '<div id="app-banner">'
            '<p class="title">Аудиотекст</p>'
            '<div class="rule"></div>'
            '<div class="fleuron">&#10087;</div>'
            '</div>'
        )
        with gr.Row():
            with gr.Column(scale=3, elem_id="text-col"):
                with gr.Row(elem_id="text-tools"):
                    paste_btn = gr.Button("📋", elem_id="paste-btn", elem_classes="icon-btn", min_width=42, scale=0)
                    clear_btn = gr.Button("🗑", elem_id="clear-btn", elem_classes="icon-btn", min_width=42, scale=0)
                text = gr.Textbox(label="Текст", lines=7, max_lines=7, placeholder="Вставьте текст…")
                file = gr.File(label="Загрузите файлы — .txt, .jpg, .png, .webp",
                               file_count="multiple",
                               file_types=[".txt", ".jpg", ".jpeg", ".png", ".webp", ".bmp", ".tiff"],
                               type="filepath", elem_id="file-up")
                btn = gr.Button("Озвучить", variant="primary", size="lg", elem_id="go-btn")
            with gr.Column(scale=2):
                audio = gr.Audio(label="Аудио — слушать и скачать", type="filepath",
                                 waveform_options=gr.WaveformOptions(waveform_color="#CFC1AE", waveform_progress_color="#CB9AA8"))
                status = gr.HTML()
        btn.click(generate, [text, file], [audio, status], show_progress="hidden")
        paste_btn.click(None, [text], [text], js=PASTE_JS)
        clear_btn.click(None, None, [text], js="() => ''")
    demo.load(None, None, None, js=TITLE_JS)

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 7860))
    demo.launch(server_name="0.0.0.0", server_port=port)
